#requires -Version 5.1
[CmdletBinding()]
param([string]$InstallRoot="$env:USERPROFILE\PathOfMelodie15Act")
$ErrorActionPreference="Stop"
$bytes=[Convert]::FromBase64String(@"

"@)
$work=Join-Path $env:TEMP "PathOfMelodie15Act.zip"
[IO.File]::WriteAllBytes($work,$bytes)
New-Item -ItemType Directory -Force -Path $InstallRoot | Out-Null
Expand-Archive -Path $work -DestinationPath $InstallRoot -Force
Remove-Item $work -Force
Write-Host ""
Write-Host "PATH OF MELODIE — 15 ACT FOUNDATION INSTALLED" -ForegroundColor Magenta
Write-Host "Project: $InstallRoot\project.godot" -ForegroundColor Green
Write-Host "Open project.godot with Godot 4 and press F6/F5." -ForegroundColor Cyan
